    Returns the path written. The artifact is mandatory for the gate's pairwise
    rho computation.
    """
    if grid is None:
        grid = canonical_grid(prices)
    art_path = Path('factors') / f'{factor_id}_signal.npy'
    arr = save_signal_artifact(panel, grid, art_path)
